begin;
set local lock_timeout='5s';
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
grant usage on schema private to service_role;
create table private.site_content_definitions(
 slug text primary key, kind text not null check(kind in ('page','global','config')),
 definition jsonb not null, required_core boolean not null default true, route text
);
alter table private.site_content_definitions enable row level security;
revoke all on private.site_content_definitions from public,anon,authenticated;
grant select on private.site_content_definitions to service_role;
create table public.site_content_drafts(
 slug text primary key check(length(slug)<=80 and slug~'^[a-z0-9]+(-[a-z0-9]+)*$'),
 definition_slug text not null references private.site_content_definitions(slug),
 kind text not null check(kind in ('page','global','config')), title text not null check(length(title) between 1 and 200),
 route text unique,content jsonb not null check(jsonb_typeof(content)='object' and octet_length(content::text)<=131072),
 version bigint not null check(version>0),updated_at timestamptz not null default now(),
 updated_by uuid references auth.users(id) on delete set null
);
create table public.site_documents(
 slug text primary key references public.site_content_drafts(slug),kind text not null check(kind in ('page','global','config')),
 title text not null,route text unique,content jsonb not null,version bigint not null,
 updated_at timestamptz not null default now(),published_at timestamptz not null default now()
);
create table public.site_content_revisions(
 id uuid primary key default gen_random_uuid(),slug text not null references public.site_content_drafts(slug),
 version bigint not null,action text not null check(action in ('create','save','publish','unpublish','restore')),
 title text not null,content jsonb not null,created_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default now(),unique(slug,version)
);
create index site_content_revisions_created_by_idx on public.site_content_revisions(created_by) where created_by is not null;
create index site_content_drafts_updated_by_idx on public.site_content_drafts(updated_by) where updated_by is not null;
create index site_content_drafts_definition_idx on public.site_content_drafts(definition_slug);
alter table public.site_content_drafts enable row level security;
alter table public.site_documents enable row level security;
alter table public.site_content_revisions enable row level security;
revoke all on public.site_content_drafts,public.site_documents,public.site_content_revisions from public,anon,authenticated;
grant select on public.site_documents to anon,authenticated;
grant select on public.site_content_drafts,public.site_content_revisions to authenticated;
grant all on public.site_content_drafts,public.site_documents,public.site_content_revisions to service_role;
create policy "Published website content" on public.site_documents for select to anon,authenticated using(true);
create policy "Active content administrators read drafts" on public.site_content_drafts for select to authenticated
 using(exists(select 1 from public.admin_users a where a.auth_user_id=(select auth.uid()) and a.is_active and a.role in ('OWNER','STAFF')));
create policy "Active content administrators read revisions" on public.site_content_revisions for select to authenticated
 using(exists(select 1 from public.admin_users a where a.auth_user_id=(select auth.uid()) and a.is_active and a.role in ('OWNER','STAFF')));

create or replace function private.validate_site_content_field(p_value jsonb,p_field jsonb,p_depth integer default 0)
returns void language plpgsql security invoker set search_path='' as $validator$
declare v_type text:=p_field->>'type';v_child jsonb;v_key text;v_text text;v_n numeric;v_count integer;
begin
 if p_depth>12 or p_value is null then raise exception 'Invalid content shape' using errcode='22023';end if;
 if v_type='object' then
  if jsonb_typeof(p_value) is distinct from 'object' then raise exception 'Expected content object' using errcode='22023';end if;
  if exists(select 1 from jsonb_object_keys(p_value) k where k in ('__proto__','constructor','prototype') or not exists(select 1 from jsonb_array_elements(p_field->'fields') f where f->>'key'=k)) then raise exception 'Unknown content field' using errcode='22023';end if;
  for v_child in select value from jsonb_array_elements(p_field->'fields') loop
   v_key:=v_child->>'key';
   if not(p_value?v_key) then raise exception 'Missing content field' using errcode='22023';end if;
   perform private.validate_site_content_field(p_value->v_key,v_child,p_depth+1);
  end loop;
 elsif v_type='list' then
  if jsonb_typeof(p_value) is distinct from 'array' then raise exception 'Expected content list' using errcode='22023';end if;
  v_count:=jsonb_array_length(p_value);
  if v_count<coalesce((p_field->>'min')::int,0) or v_count>coalesce((p_field->>'max')::int,100) then raise exception 'Invalid content list length' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_value) e where jsonb_typeof(e)='object' and e?'id' group by e->>'id' having count(*)>1) then raise exception 'Duplicate content IDs' using errcode='22023';end if;
  for v_child in select value from jsonb_array_elements(p_value) loop perform private.validate_site_content_field(v_child,p_field->'item',p_depth+1);end loop;
 elsif v_type='boolean' then
  if jsonb_typeof(p_value) is distinct from 'boolean' then raise exception 'Expected content boolean' using errcode='22023';end if;
 elsif v_type='number' then
  if jsonb_typeof(p_value) is distinct from 'number' then raise exception 'Expected content number' using errcode='22023';end if;
  v_n:=(p_value#>>'{}')::numeric;
  if v_n<coalesce((p_field->>'min')::numeric,0) or v_n>coalesce((p_field->>'max')::numeric,1000000000) then raise exception 'Content number out of range' using errcode='22023';end if;
 else
  if jsonb_typeof(p_value) is distinct from 'string' then raise exception 'Expected content text' using errcode='22023';end if;
  v_text:=p_value#>>'{}';
  if length(v_text)>coalesce((p_field->>'maxLength')::int,16000) or coalesce((p_field->>'required')::boolean,false) and btrim(v_text)='' or regexp_replace(v_text,E'[\n\r\t]','','g')~'[[:cntrl:]]' then raise exception 'Invalid content text (%)',p_field->>'key' using errcode='22023';end if;
  if v_text<>'' and v_type in ('image','url') then
   if v_text~'[[:space:]\\]' or v_text like '//%' then raise exception 'Unsafe content URL' using errcode='22023';end if;
   if v_type='image' then
    if not(v_text~'^/[^\\[:space:]#]*$' or v_text~'^https://images[.]unsplash[.]com/[^\\[:space:]#]*$' or v_text~'^https://fyqmbjzpajmnyyqcrmgc[.]supabase[.]co/storage/v1/object/public/product-images/[^\\[:space:]#]*$') then raise exception 'Invalid image URL' using errcode='22023';end if;
   elsif not(v_text~'^/[^\\[:space:]]*$' or v_text~'^#[A-Za-z][A-Za-z0-9_-]*$' or v_text~'^mailto:[^?@[:space:]]+@[^?@[:space:]]+[.][^?@[:space:]]+([?][^[:cntrl:]]*)?$' or v_text~'^tel:[+]?[0-9()-]{5,25}$' or v_text~'^https://[^/@\\[:space:]]+([/?#][^\\[:space:]]*)?$') then raise exception 'Invalid website URL' using errcode='22023';end if;
  end if;
  if v_type='select' and not exists(select 1 from jsonb_array_elements(p_field->'options') o where o->>'value'=v_text) then raise exception 'Invalid content selection' using errcode='22023';end if;
 end if;
end $validator$;
revoke all on function private.validate_site_content_field(jsonb,jsonb,integer) from public,anon,authenticated;

create or replace function private.validate_site_content(p_content jsonb,p_definition jsonb,p_slug text)
returns void language plpgsql security invoker set search_path='' as $validator$
declare rule record;question jsonb;v_values jsonb;
begin
 if p_content is null or octet_length(p_content::text)>131072 then raise exception 'Content exceeds size limit' using errcode='22023';end if;
 perform private.validate_site_content_field(p_content,jsonb_build_object('type','object','fields',p_definition->'fields'));
 if p_definition?'routineOptions' then
  for rule in select key,value from jsonb_each(p_definition->'routineOptions') loop
   select e into question from jsonb_array_elements(p_content->'questions') e where e->>'id'=rule.key;
   select jsonb_agg(e->>'value' order by e->>'value') into v_values from jsonb_array_elements(question->'options') e;
   if v_values is distinct from (select jsonb_agg(e order by e) from jsonb_array_elements_text(rule.value) e) then raise exception 'Keep supported routine choices' using errcode='22023';end if;
  end loop;
 end if;
 if p_slug='site' and not(coalesce(p_content#>>'{config,url}','')~'^https://[^/@?#\\[:space:]]+/?$') then raise exception 'Website URL must be HTTPS origin' using errcode='22023';end if;
end $validator$;
revoke all on function private.validate_site_content(jsonb,jsonb,text) from public,anon,authenticated;

create or replace function public.mutate_site_content(
 p_slug text,p_action text,p_expected_version bigint,p_title text default null,p_content jsonb default null,p_revision_id uuid default null
) returns jsonb language plpgsql security definer set search_path='' as $mutation$
declare v_role text;v_actor uuid:=auth.uid();v_draft public.site_content_drafts%rowtype;v_definition private.site_content_definitions%rowtype;
 v_title text;v_content jsonb;v_version bigint;v_route text;v_kind text;
begin
 select a.role into v_role from public.admin_users a where a.auth_user_id=v_actor and a.is_active and a.role in ('OWNER','STAFF');
 if v_role is null then raise exception 'Active administrator required' using errcode='42501';end if;
 if p_slug is null or length(p_slug)>80 or p_slug!~'^[a-z0-9]+(-[a-z0-9]+)*$' or p_action is null or p_action not in ('create','save','publish','unpublish','restore') or p_expected_version is null or p_expected_version<0 then raise exception 'Invalid content action' using errcode='22023';end if;
 if p_action in ('publish','unpublish') and v_role<>'OWNER' then raise exception 'Owner required for publication' using errcode='42501';end if;
 -- Serialize the same slug, including concurrent creates, without a global lock.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('seedly-content:'||p_slug,0));
 select * into v_draft from public.site_content_drafts where slug=p_slug for update;
 if p_action='create' then
  if found then raise exception 'Content slug already exists' using errcode='23505';end if;
  if p_expected_version<>0 or exists(select 1 from private.site_content_definitions where slug=p_slug) then raise exception 'Reserved content slug' using errcode='22023';end if;
  select * into v_definition from private.site_content_definitions where slug='page-template';
  v_version:=1;v_route:='/pages/'||p_slug;v_kind:='page';
 else
  if not found then raise exception 'Content document not found' using errcode='P0002';end if;
  if v_draft.version<>p_expected_version then raise exception 'Content changed since loaded' using errcode='40001';end if;
  select * into v_definition from private.site_content_definitions where slug=v_draft.definition_slug;
  v_version:=v_draft.version+1;v_route:=v_draft.route;v_kind:=v_draft.kind;
 end if;
 if p_action='unpublish' and v_draft.definition_slug<>'page-template' then raise exception 'Required website content cannot be unpublished' using errcode='22023';end if;
 if p_action='restore' then
  select title,content into v_title,v_content from public.site_content_revisions where slug=p_slug and id=p_revision_id;
  if not found then raise exception 'Revision not found for this document' using errcode='P0002';end if;
 elsif p_action='unpublish' then
  v_title:=v_draft.title;v_content:=v_draft.content;
 else
  v_title:=coalesce(p_title,v_draft.title);v_content:=coalesce(p_content,v_draft.content);
 end if;
 if v_title is null or length(btrim(v_title)) not between 1 and 200 or v_title~'[[:cntrl:]]' then raise exception 'Invalid document title' using errcode='22023';end if;
 perform private.validate_site_content(v_content,v_definition.definition,p_slug);
 if p_action='create' then
  insert into public.site_content_drafts(slug,definition_slug,kind,title,route,content,version,updated_by) values(p_slug,'page-template',v_kind,btrim(v_title),v_route,v_content,v_version,v_actor);
 else
  update public.site_content_drafts set title=btrim(v_title),content=v_content,version=v_version,updated_at=now(),updated_by=v_actor where slug=p_slug;
 end if;
 insert into public.site_content_revisions(slug,version,action,title,content,created_by) values(p_slug,v_version,p_action,btrim(v_title),v_content,v_actor);
 if p_action='publish' then
  insert into public.site_documents(slug,kind,title,route,content,version,updated_at,published_at) values(p_slug,v_kind,btrim(v_title),v_route,v_content,v_version,now(),now())
   on conflict(slug) do update set title=excluded.title,content=excluded.content,version=excluded.version,updated_at=excluded.updated_at,published_at=excluded.published_at;
 elsif p_action='unpublish' then delete from public.site_documents where slug=p_slug;
 end if;
 return jsonb_build_object('slug',p_slug,'version',v_version);
end $mutation$;
revoke all on function public.mutate_site_content(text,text,bigint,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function public.mutate_site_content(text,text,bigint,text,jsonb,uuid) to authenticated;

create table public.site_change_events(
 event_id bigint generated always as identity primary key,topic text not null default 'store' check(topic='store'),
 created_at timestamptz not null default now()
);
alter table public.site_change_events enable row level security;
revoke all on public.site_change_events from public,anon,authenticated;
grant select on public.site_change_events to anon,authenticated;
grant all on public.site_change_events to service_role;
grant usage,select on sequence public.site_change_events_event_id_seq to service_role;
create policy "Public generic store invalidations" on public.site_change_events for select to anon,authenticated using(true);
create or replace function private.emit_site_change() returns trigger language plpgsql security definer set search_path='' as $event$
declare v_id bigint;
begin
 insert into public.site_change_events default values returning event_id into v_id;
 if v_id%1000=0 then delete from public.site_change_events where event_id<v_id-1000;end if;
 return null;
end $event$;
revoke all on function private.emit_site_change() from public,anon,authenticated;
do $triggers$
declare relation text;
begin
 foreach relation in array array['site_documents','products','product_variants','kits','kit_items','categories','site_settings','reviews'] loop
  execute format('create trigger store_content_changed after insert or update or delete on public.%I for each statement execute function private.emit_site_change()',relation);
 end loop;
 if not exists(select 1 from pg_publication where pubname='supabase_realtime') then create publication supabase_realtime;end if;
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='site_change_events') then alter publication supabase_realtime add table public.site_change_events;end if;
end $triggers$;
create or replace function public.get_site_content_snapshot() returns jsonb
language sql stable security invoker set search_path='' as $snapshot$
 select jsonb_build_object('documents',coalesce((select jsonb_object_agg(d.slug,to_jsonb(d)) from public.site_documents d),'{}'::jsonb),
 'revision',(select coalesce(max(event_id),0)::text from public.site_change_events));
$snapshot$;
revoke all on function public.get_site_content_snapshot() from public,anon,authenticated;
grant execute on function public.get_site_content_snapshot() to anon,authenticated,service_role;

create table private.api_rate_limits(bucket text primary key,hits integer not null,reset_at timestamptz not null);
create index api_rate_limits_reset_idx on private.api_rate_limits(reset_at);
alter table private.api_rate_limits enable row level security;
revoke all on private.api_rate_limits from public,anon,authenticated;
grant select,insert,update,delete on private.api_rate_limits to service_role;
create or replace function public.consume_rate_limit(p_bucket text,p_limit integer,p_window_seconds integer)
returns jsonb language plpgsql security invoker set search_path='' as $limit$
declare v_reset timestamptz;v_now timestamptz:=clock_timestamp();
begin
 if p_bucket is null or length(p_bucket) not between 1 and 128 or p_limit is null or p_limit not between 1 and 10000 or p_window_seconds is null or p_window_seconds not between 1 and 86400 then raise exception 'Invalid rate limit' using errcode='22023';end if;
 insert into private.api_rate_limits(bucket,hits,reset_at) values(p_bucket,1,v_now+make_interval(secs=>p_window_seconds))
 on conflict(bucket) do update set hits=case when api_rate_limits.reset_at<=v_now then 1 else api_rate_limits.hits+1 end,
 reset_at=case when api_rate_limits.reset_at<=v_now then v_now+make_interval(secs=>p_window_seconds) else api_rate_limits.reset_at end
 where api_rate_limits.reset_at<=v_now or api_rate_limits.hits<p_limit returning reset_at into v_reset;
 if not found then
  select reset_at into v_reset from private.api_rate_limits where bucket=p_bucket;
  return jsonb_build_object('allowed',false,'retry_after_seconds',greatest(1,ceil(extract(epoch from coalesce(v_reset,v_now+make_interval(secs=>p_window_seconds))-v_now))::integer));
 end if;
 -- Bounded opportunistic cleanup avoids an unbounded background transaction.
 if pg_catalog.hashtextextended(p_bucket,0)%100=0 then
  delete from private.api_rate_limits where bucket in(select bucket from private.api_rate_limits where reset_at<v_now-interval '1 hour' limit 1000);
 end if;
 return jsonb_build_object('allowed',true,'retry_after_seconds',0);
end $limit$;
revoke all on function public.consume_rate_limit(text,integer,integer) from public,anon,authenticated;
grant execute on function public.consume_rate_limit(text,integer,integer) to service_role;

-- Public reviews must use server validation, bot controls and the durable limiter.
drop policy if exists "Public can submit pending reviews" on public.reviews;
revoke insert on public.reviews from anon,authenticated;
-- Staff can still moderate existing reviews under the existing admin policy.
insert into public.site_settings(key,value) values('ordering_enabled','true'),('cod_enabled','true'),('bank_transfer_enabled','true'),('wallet_enabled','true') on conflict(key) do nothing;
drop policy if exists "Public can view non-sensitive site settings" on public.site_settings;
create policy "Public can view non-sensitive site settings" on public.site_settings for select to anon,authenticated using(key=any(array[
 'store_name','tagline','currency','delivery_fee_minor','free_delivery_threshold_minor','bank_name','bank_account_title','bank_account_number','bank_iban',
 'jazzcash_number','jazzcash_title','easypaisa_number','easypaisa_title','whatsapp_number','support_email','serviceable_cities',
 'ordering_enabled','cod_enabled','bank_transfer_enabled','wallet_enabled'
]));
CREATE OR REPLACE FUNCTION public.create_order_transactional(p_order_id text, p_order_number text, p_customer_name text, p_customer_email text, p_customer_phone text, p_shipping_address text, p_shipping_city text, p_shipping_province text, p_shipping_postal_code text, p_shipping_notes text, p_payment_method text, p_receipt_path text, p_idempotency_key text, p_request_fingerprint text, p_tracking_token_hash text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_existing_order record;
  v_payment_status text;
  v_order_status text;
  v_free_thresh integer;
  v_delivery_fee integer;
  v_subtotal integer := 0;
  v_shipping integer := 0;
  v_total integer := 0;
  v_item record;
  r_var record;
  v_item_id text;
  v_line_total integer;
BEGIN
  if coalesce(p_idempotency_key,'') !~ '^[A-Za-z0-9_-]{20,100}$' or coalesce(p_request_fingerprint,'') !~ '^[a-f0-9]{64}$' or coalesce(p_tracking_token_hash,'') !~ '^[a-f0-9]{64}$' or coalesce(p_order_number,'') !~ '^SED-([0-9]{6,12}|[A-F0-9]{24})$' then raise exception 'Invalid checkout identity' using errcode='22023'; end if;
  if p_payment_method not in ('COD','bank_transfer','wallet_aggregator') or char_length(coalesce(p_customer_name,'')) not between 2 and 500 or char_length(coalesce(p_customer_email,'')) not between 3 and 254 or char_length(coalesce(p_shipping_address,'')) not between 8 and 500 then raise exception 'Invalid checkout details' using errcode='22023'; end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'Invalid items' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_items)e where jsonb_typeof(e)<>'object' or coalesce(e->>'quantity','') !~ '^[1-9][0-9]?$' or (e->>'kit_id' is null and e->>'variant_id' is null) or (e->>'kit_id' is not null and (e->>'variant_id' is not null or e->>'product_id' is distinct from e->>'kit_id'))) then raise exception 'Invalid line selection' using errcode='22023'; end if;
  if (select count(distinct coalesce(e->>'kit_id',e->>'variant_id')) from jsonb_array_elements(p_items)e) <> jsonb_array_length(p_items) then raise exception 'Duplicate packs' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('seedly-checkout:'||p_idempotency_key,0));
  -- 1. Idempotency Check
  IF p_idempotency_key IS NOT NULL AND TRIM(p_idempotency_key) != '' THEN
    SELECT id, order_number, subtotal_minor, shipping_minor, total_minor, payment_status, order_status, request_fingerprint
    INTO v_existing_order
    FROM public.orders
    WHERE idempotency_key = p_idempotency_key;

    IF FOUND THEN
      IF v_existing_order.request_fingerprint IS DISTINCT FROM p_request_fingerprint THEN
        RAISE EXCEPTION 'Idempotency conflict: key reused with different request fingerprint'
          USING ERRCODE = 'P0001';
      ELSE
        RETURN jsonb_build_object(
          'order_id', v_existing_order.id,
          'order_number', v_existing_order.order_number,
          'subtotal_minor', v_existing_order.subtotal_minor,
          'shipping_minor', v_existing_order.shipping_minor,
          'total_minor', v_existing_order.total_minor,
          'payment_status', v_existing_order.payment_status,
          'order_status', v_existing_order.order_status,
          'is_idempotent_replay', true
        );
      END IF;
    END IF;
  END IF;

  -- Latest owner controls are enforced after committed idempotent recovery.
  perform s.key from public.site_settings s where s.key in ('ordering_enabled','cod_enabled','bank_transfer_enabled','wallet_enabled','bank_name','bank_account_title','bank_account_number','jazzcash_number','jazzcash_title','easypaisa_number','easypaisa_title','delivery_fee_minor','free_delivery_threshold_minor') order by s.key for share;
  if not exists(select 1 from public.site_settings where key='ordering_enabled' and value='true') then raise exception 'Ordering is temporarily unavailable' using errcode='P0006';end if;
  if p_payment_method='COD' and not exists(select 1 from public.site_settings where key='cod_enabled' and value='true')
   or p_payment_method='bank_transfer' and (not exists(select 1 from public.site_settings where key='bank_transfer_enabled' and value='true') or (select count(*) from public.site_settings where key in ('bank_name','bank_account_title','bank_account_number') and btrim(value)<>'')<>3)
   or p_payment_method='wallet_aggregator' and (not exists(select 1 from public.site_settings where key='wallet_enabled' and value='true') or not((select count(*) from public.site_settings where key in ('jazzcash_number','jazzcash_title') and btrim(value)<>'')=2 or (select count(*) from public.site_settings where key in ('easypaisa_number','easypaisa_title') and btrim(value)<>'')=2))
  then raise exception 'Selected payment method is unavailable' using errcode='P0006';end if;

  -- 2. Validate Items
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Order items cannot be empty' USING ERRCODE = 'P0005';
  END IF;


  -- Lock catalog rows so prices, component definitions and shipping settings stay
  -- stable for the whole transaction. Parent rows are locked before variants.
  perform p.id from public.products p where p.id in (select e->>'product_id' from jsonb_array_elements(p_items)e where e->>'kit_id' is null union select ki.product_id from public.kit_items ki where ki.kit_id in (select e->>'kit_id' from jsonb_array_elements(p_items)e)) order by p.id for share;
  perform k.id from public.kits k where k.id in (select e->>'kit_id' from jsonb_array_elements(p_items)e) order by k.id for share;
  perform ki.id from public.kit_items ki where ki.kit_id in (select e->>'kit_id' from jsonb_array_elements(p_items)e) order by ki.id for share;
  perform s.key from public.site_settings s where s.key in ('delivery_fee_minor','free_delivery_threshold_minor') order by s.key for share;
  for v_item in select e->>'product_id' product_id,e->>'variant_id' variant_id,e->>'kit_id' kit_id from jsonb_array_elements(p_items)e loop
    if v_item.kit_id is null then
      if not exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=v_item.variant_id and pv.product_id=v_item.product_id and pv.status='ACTIVE' and p.status='ACTIVE') then raise exception 'Invalid active pack ownership' using errcode='P0003'; end if;
    else
      if not exists(select 1 from public.kits k where k.id=v_item.kit_id and k.status='ACTIVE') or not exists(select 1 from public.kit_items ki where ki.kit_id=v_item.kit_id) or exists(select 1 from public.kit_items ki left join public.product_variants pv on pv.id=coalesce(ki.variant_id,ki.product_variant_id) left join public.products p on p.id=ki.product_id where ki.kit_id=v_item.kit_id and (pv.id is null or pv.product_id is distinct from ki.product_id or pv.status<>'ACTIVE' or p.status<>'ACTIVE')) then raise exception 'Invalid active kit component' using errcode='P0003'; end if;
    end if;
  end loop;

  -- 3. Lock affected product variants in consistent order (ASC) to prevent deadlocks
  -- Calculate demands
  FOR r_var IN (
    WITH raw_items AS (
      SELECT
        (elem->>'product_id') as product_id,
        (elem->>'variant_id') as variant_id,
        (elem->>'kit_id') as kit_id,
        (elem->>'quantity')::int as quantity
      FROM jsonb_array_elements(p_items) elem
    ),
    direct_demand AS (
      SELECT variant_id, SUM(quantity)::int as qty
      FROM raw_items
      WHERE kit_id IS NULL AND variant_id IS NOT NULL
      GROUP BY variant_id
    ),
    kit_demand AS (
      SELECT
        COALESCE(ki.variant_id, ki.product_variant_id) as variant_id,
        SUM(ri.quantity * ki.quantity)::int as qty
      FROM raw_items ri
      JOIN public.kit_items ki ON ki.kit_id = ri.kit_id
      WHERE ri.kit_id IS NOT NULL
      GROUP BY COALESCE(ki.variant_id, ki.product_variant_id)
    ),
    combined_demand AS (
      SELECT variant_id, SUM(qty)::int as total_qty
      FROM (
        SELECT * FROM direct_demand
        UNION ALL
        SELECT * FROM kit_demand
      ) c
      WHERE variant_id IS NOT NULL
      GROUP BY variant_id
    )
    SELECT
      pv.id as variant_id,
      pv.inventory_quantity,
      pv.status as variant_status,
      cd.total_qty,
      p.name as product_name,
      pv.option_value
    FROM public.product_variants pv
    JOIN combined_demand cd ON cd.variant_id = pv.id
    JOIN public.products p ON p.id = pv.product_id
    ORDER BY pv.id ASC
    FOR UPDATE OF pv
  ) LOOP
    IF r_var.variant_status != 'ACTIVE' THEN
      RAISE EXCEPTION 'Product variant "% (%)" is not active', r_var.product_name, r_var.option_value
        USING ERRCODE = 'P0003';
    END IF;

    IF r_var.inventory_quantity < r_var.total_qty THEN
      RAISE EXCEPTION 'Insufficient stock for "% (%)". Available: %, Requested: %',
        r_var.product_name, r_var.option_value, r_var.inventory_quantity, r_var.total_qty
        USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  -- 4. Decrement inventory for locked variants
  WITH raw_items AS (
    SELECT
      (elem->>'product_id') as product_id,
      (elem->>'variant_id') as variant_id,
      (elem->>'kit_id') as kit_id,
      (elem->>'quantity')::int as quantity
    FROM jsonb_array_elements(p_items) elem
  ),
  direct_demand AS (
    SELECT variant_id, SUM(quantity)::int as qty
    FROM raw_items
    WHERE kit_id IS NULL AND variant_id IS NOT NULL
    GROUP BY variant_id
  ),
  kit_demand AS (
    SELECT
      COALESCE(ki.variant_id, ki.product_variant_id) as variant_id,
      SUM(ri.quantity * ki.quantity)::int as qty
    FROM raw_items ri
    JOIN public.kit_items ki ON ki.kit_id = ri.kit_id
    WHERE ri.kit_id IS NOT NULL
    GROUP BY COALESCE(ki.variant_id, ki.product_variant_id)
  ),
  combined_demand AS (
    SELECT variant_id, SUM(qty)::int as total_qty
    FROM (
      SELECT * FROM direct_demand
      UNION ALL
      SELECT * FROM kit_demand
    ) c
    WHERE variant_id IS NOT NULL
    GROUP BY variant_id
  )
  UPDATE public.product_variants pv
  SET inventory_quantity = pv.inventory_quantity - cd.total_qty,
      updated_at = NOW()
  FROM combined_demand cd
  WHERE pv.id = cd.variant_id;

  -- 5. Calculate Subtotal from authoritative catalog prices
  FOR v_item IN (
    SELECT
      (elem->>'product_id') as product_id,
      (elem->>'variant_id') as variant_id,
      (elem->>'kit_id') as kit_id,
      (elem->>'quantity')::int as quantity
    FROM jsonb_array_elements(p_items) elem
  ) LOOP
    IF v_item.kit_id IS NOT NULL THEN
      SELECT price_minor INTO v_line_total
      FROM public.kits
      WHERE id = v_item.kit_id AND status = 'ACTIVE';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Kit % is not active or does not exist', v_item.kit_id USING ERRCODE = 'P0003';
      END IF;
      v_subtotal := v_subtotal + (v_line_total * v_item.quantity);
    ELSIF v_item.variant_id IS NOT NULL THEN
      SELECT price_minor INTO v_line_total
      FROM public.product_variants
      WHERE id = v_item.variant_id AND status = 'ACTIVE';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Variant % is not active or does not exist', v_item.variant_id USING ERRCODE = 'P0003';
      END IF;
      v_subtotal := v_subtotal + (v_line_total * v_item.quantity);
    ELSE
      SELECT price_minor INTO v_line_total
      FROM public.products
      WHERE id = v_item.product_id AND status = 'ACTIVE';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Product % is not active or does not exist', v_item.product_id USING ERRCODE = 'P0003';
      END IF;
      v_subtotal := v_subtotal + (v_line_total * v_item.quantity);
    END IF;
  END LOOP;

  -- 6. Shipping & Total Calculation
  SELECT COALESCE((SELECT value::int FROM public.site_settings WHERE key = 'free_delivery_threshold_minor'), 200000) INTO v_free_thresh;
  SELECT COALESCE((SELECT value::int FROM public.site_settings WHERE key = 'delivery_fee_minor'), 20000) INTO v_delivery_fee;

  IF v_subtotal >= v_free_thresh THEN
    v_shipping := 0;
  ELSE
    v_shipping := v_delivery_fee;
  END IF;

  v_total := v_subtotal + v_shipping;

  -- 7. Determine initial order and payment status
  IF p_payment_method = 'COD' THEN
    v_payment_status := 'PENDING';
    v_order_status := 'RECEIVED';
  ELSIF p_payment_method = 'wallet_aggregator' OR (p_receipt_path IS NOT NULL AND TRIM(p_receipt_path) != '') THEN
    v_payment_status := 'UNDER_REVIEW';
    v_order_status := 'PAYMENT_REVIEW';
  ELSE
    v_payment_status := 'PENDING';
    v_order_status := 'PENDING_PAYMENT';
  END IF;

  -- 8. Insert Order
  INSERT INTO public.orders (
    id, order_number, customer_name, customer_email, customer_phone,
    shipping_address, shipping_city, shipping_province, shipping_postal_code,
    shipping_notes, currency, subtotal_minor, shipping_minor, discount_minor,
    total_minor, payment_method, payment_status, order_status,
    receipt_path, idempotency_key, request_fingerprint, tracking_token_hash,
    created_at, updated_at
  ) VALUES (
    p_order_id, p_order_number, p_customer_name, p_customer_email, p_customer_phone,
    p_shipping_address, p_shipping_city, p_shipping_province, p_shipping_postal_code,
    p_shipping_notes, 'PKR', v_subtotal, v_shipping, 0,
    v_total, p_payment_method, v_payment_status, v_order_status,
    p_receipt_path, p_idempotency_key, p_request_fingerprint, p_tracking_token_hash,
    NOW(), NOW()
  );

  -- 9. Insert Line Items
  FOR v_item IN (
    SELECT
      elem->>'id' as item_id,
      elem->>'product_id' as product_id,
      elem->>'variant_id' as variant_id,
      elem->>'kit_id' as kit_id,
      (elem->>'quantity')::int as quantity,
      elem->>'name' as client_name,
      elem->>'sku' as client_sku,
      elem->>'image_url' as client_image
    FROM jsonb_array_elements(p_items) elem
  ) LOOP
    v_item_id := 'oi-' || gen_random_uuid();

    IF v_item.kit_id IS NOT NULL THEN
      DECLARE
        k_rec record;
      BEGIN
        SELECT name, price_minor, image_url INTO k_rec FROM public.kits WHERE id = v_item.kit_id;
        INSERT INTO public.order_items (
          id, order_id, product_id, kit_id, variant_id,
          product_name, variant_name, price_minor, quantity, line_total_minor,
          name_snapshot, sku_snapshot, image_url, unit_price_minor,
          created_at, updated_at
        ) VALUES (
          v_item_id, p_order_id, NULL, v_item.kit_id, NULL,
          k_rec.name, NULL, k_rec.price_minor, v_item.quantity, k_rec.price_minor * v_item.quantity,
          k_rec.name, COALESCE(v_item.client_sku, 'KIT-' || v_item.kit_id), COALESCE(k_rec.image_url, v_item.client_image), k_rec.price_minor,
          NOW(), NOW()
        );
      END;
    ELSE
      DECLARE
        p_rec record;
        var_rec record;
        v_name text;
        v_var_name text := NULL;
        v_price int;
        v_sku text;
        v_img text;
      BEGIN
        SELECT name, price_minor, sku, image_url INTO p_rec FROM public.products WHERE id = v_item.product_id;
        v_name := p_rec.name;
        v_price := p_rec.price_minor;
        v_sku := p_rec.sku;
        v_img := p_rec.image_url;

        IF v_item.variant_id IS NOT NULL THEN
          SELECT option_value, price_minor, sku INTO var_rec FROM public.product_variants WHERE id = v_item.variant_id;
          v_var_name := var_rec.option_value;
          v_price := var_rec.price_minor;
          v_sku := var_rec.sku;
          v_name := p_rec.name || ' (' || var_rec.option_value || ')';
        END IF;

        INSERT INTO public.order_items (
          id, order_id, product_id, kit_id, variant_id,
          product_name, variant_name, price_minor, quantity, line_total_minor,
          name_snapshot, sku_snapshot, image_url, unit_price_minor,
          created_at, updated_at
        ) VALUES (
          v_item_id, p_order_id, v_item.product_id, NULL, v_item.variant_id,
          p_rec.name, v_var_name, v_price, v_item.quantity, v_price * v_item.quantity,
          v_name, COALESCE(v_sku, v_item.client_sku), COALESCE(v_img, v_item.client_image), v_price,
          NOW(), NOW()
        );
      END;
    END IF;
  END LOOP;

  -- Snapshot the exact reserved variants, including kit components.
  insert into public.order_stock_reservations(order_id,variant_id,quantity)
  with direct as (select e->>'variant_id' variant_id,(e->>'quantity')::int quantity from jsonb_array_elements(p_items)e where e->>'kit_id' is null), kits as (select coalesce(ki.variant_id,ki.product_variant_id) variant_id,ki.quantity*(e->>'quantity')::int quantity from jsonb_array_elements(p_items)e join public.kit_items ki on ki.kit_id=e->>'kit_id'), combined as (select * from direct union all select * from kits) select p_order_id,variant_id,sum(quantity)::int from combined group by variant_id;
  -- 10. Audit event
  INSERT INTO public.order_events (
    id, order_id, actor_type, actor_id, event_type, old_status, new_status, metadata, created_at
  ) VALUES (
    gen_random_uuid(), p_order_id, 'CUSTOMER', NULL, 'ORDER_CREATED', NULL, v_order_status,
    jsonb_build_object('payment_status', v_payment_status, 'payment_method', p_payment_method),
    NOW()
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'order_number', p_order_number,
    'subtotal_minor', v_subtotal,
    'shipping_minor', v_shipping,
    'total_minor', v_total,
    'payment_status', v_payment_status,
    'order_status', v_order_status,
    'is_idempotent_replay', false
  );
END;
