ns","type":"list","min":6,"max":6,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"id","label":"Id","type":"select","required":true,"options":[{"value":"page_section_01","label":"page section 01"},{"value":"page_section_02","label":"page section 02"},{"value":"page_section_03","label":"page section 03"},{"value":"page_section_04","label":"page section 04"},{"value":"testimonials","label":"testimonials"},{"value":"page_section_05","label":"page section 05"}],"maxLength":80},{"key":"enabled","label":"Enabled","type":"boolean"}]}},{"key":"collections","label":"Collections","type":"list","min":0,"max":100,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"title","label":"Title","type":"text","required":true,"maxLength":500},{"key":"text","label":"Text","type":"textarea","required":true,"maxLength":16000},{"key":"href","label":"Href","type":"url","required":true,"maxLength":2048},{"key":"image","label":"Image","type":"image","required":true,"maxLength":2048}]}},{"key":"featuredKitSlug","label":"Featured Kit Slug","type":"text","required":true,"maxLength":500}]},"route":"/"},{"slug":"about","kind":"page","title":"Our story","description":"Website content and search information for Our story.","publish":true,"content":{"seo":{"title":"Our story | Seedly","description":"Get to know the Seedly collection: pantry seeds, loose-leaf teas and seed cycling kits, with ingredients, pack sizes and preparation details on every product page."},"copy":{"alt_seedly_pumpkin_seeds_sesame_and_chamomile_on_a_kitchen":"Seedly pumpkin seeds, sesame and chamomile on a kitchen table","alt_founder":"Founder"},"links":{"href_shop":"/shop","href_find_your_seed":"/find-your-seed","href_seeds":"/seeds"},"images":{"src_images_hero_seedly_hero_lifestyle_jpg":"/images/hero/seedly-hero-lifestyle.jpg","hero":"/images/hero/seedly-hero-lifestyle.jpg"},"sections":[{"id":"page_section_01","enabled":true},{"id":"page_section_02","enabled":true},{"id":"page_section_03","enabled":true},{"id":"page_section_04","enabled":true},{"id":"page_section_05","enabled":true}],"story":{"hero":{"eyebrow":"Our story","h1":"Everyday ingredients. A place in your kitchen.","lead":"A spoonful of seeds over breakfast. A pot of tea in the afternoon. Seedly is built around ingredients that fit into the way you already eat and drink.","primaryCta":"Browse the collection","secondaryCta":"Routine finder"},"whySeedly":{"eyebrow":"Why Seedly","h2":"Honest ingredients, packed fresh.","paragraph1":"Seedly is a pantry shop based in Lahore. Explore seeds, seed kits and teas with ingredients, pack sizes and preparation details on each product page.","paragraph2":"Choose the ingredients that fit your everyday meals and ask our customer care team when you need help.","signature":""},"sourceToPouch":{"h2":"From source to your kitchen.","steps":[{"step":"01","title":"Explore the ingredients","text":"Check the product page for ingredients and preparation details."},{"step":"02","title":"Choose your pack","text":"Compare the available pack sizes and current prices before ordering."},{"step":"03","title":"Keep it fresh","text":"Follow the storage instructions provided for each product."},{"step":"04","title":"Follow your delivery","text":"Courier details appear on your order page once your parcel has been dispatched."}]},"collection":{"h2":"A small, useful collection.","shopAll":"Shop all","cards":[{"id":"seeds","title":"Pantry seeds","description":"Pumpkin, flax, sunflower and sesame. Add them to breakfast, use them in baking or finish a salad with a spoonful.","count":"","linkText":"Shop seeds","href":"/seeds"},{"id":"teas","title":"Loose-leaf teas","description":"Chamomile flowers, spearmint and green tea. Choose a familiar flavour or find something different for your next cup.","count":"","linkText":"Shop teas","href":"/teas"},{"id":"kits","title":"Seed kits","description":"Our seeds, paired together in one box. Compare the two-seed and four-seed options to find the contents you need.","count":"","linkText":"Compare kits","href":"/kits"}]},"closingCta":{"h2":"Start with one ingredient.","sub":"Not sure where to begin? Try the routine finder, or ask us on WhatsApp.","primaryCta":"Shop seeds","secondaryCta":"Routine finder","whatsappCta":"Ask on WhatsApp"}}},"definition":{"slug":"about","title":"Our story","description":"Website content and search information for Our story.","kind":"page","fields":[{"key":"seo","label":"Seo","type":"object","fields":[{"key":"title","label":"Title","type":"text","required":true,"maxLength":500},{"key":"description","label":"Description","type":"textarea","required":true,"maxLength":16000}]},{"key":"copy","label":"Copy","type":"object","fields":[{"key":"alt_seedly_pumpkin_seeds_sesame_and_chamomile_on_a_kitchen","label":"Seedly pumpkin seeds sesame and chamomile on a kitchen","type":"text","required":true,"maxLength":500},{"key":"alt_founder","label":"Founder","type":"text","required":true,"maxLength":500}]},{"key":"links","label":"Links","type":"object","fields":[{"key":"href_shop","label":"Shop","type":"url","required":true,"maxLength":2048},{"key":"href_find_your_seed","label":"Find your seed","type":"url","required":true,"maxLength":2048},{"key":"href_seeds","label":"Seeds","type":"url","required":true,"maxLength":2048}]},{"key":"images","label":"Images","type":"object","fields":[{"key":"src_images_hero_seedly_hero_lifestyle_jpg","label":"Images hero seedly hero lifestyle jpg","type":"image","required":true,"maxLength":2048},{"key":"hero","label":"Hero","type":"image","required":true,"maxLength":2048}]},{"key":"sections","label":"Sections","type":"list","min":5,"max":5,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"id","label":"Id","type":"select","required":true,"options":[{"value":"page_section_01","label":"page section 01"},{"value":"page_section_02","label":"page section 02"},{"value":"page_section_03","label":"page section 03"},{"value":"page_section_04","label":"page section 04"},{"value":"page_section_05","label":"page section 05"}],"maxLength":80},{"key":"enabled","label":"Enabled","type":"boolean"}]}},{"key":"story","label":"Story","type":"object","fields":[{"key":"hero","label":"Hero","type":"object","fields":[{"key":"eyebrow","label":"Eyebrow","type":"text","required":true,"maxLength":500},{"key":"h1","label":"H1","type":"text","required":true,"maxLength":500},{"key":"lead","label":"Lead","type":"textarea","required":true,"maxLength":16000},{"key":"primaryCta","label":"Primary Cta","type":"text","required":true,"maxLength":500},{"key":"secondaryCta","label":"Secondary Cta","type":"text","required":true,"maxLength":500}]},{"key":"whySeedly","label":"Why Seedly","type":"object","fields":[{"key":"eyebrow","label":"Eyebrow","type":"text","required":true,"maxLength":500},{"key":"h2","label":"H2","type":"text","required":true,"maxLength":500},{"key":"paragraph1","label":"Paragraph1","type":"textarea","required":true,"maxLength":16000},{"key":"paragraph2","label":"Paragraph2","type":"textarea","required":true,"maxLength":16000},{"key":"signature","label":"Signature","type":"text","required":false,"maxLength":500}]},{"key":"sourceToPouch","label":"Source To Pouch","type":"object","fields":[{"key":"h2","label":"H2","type":"text","required":true,"maxLength":500},{"key":"steps","label":"Steps","type":"list","min":0,"max":100,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"step","label":"Step","type":"text","required":true,"maxLength":500},{"key":"title","label":"Title","type":"text","required":true,"maxLength":500},{"key":"text","label":"Text","type":"textarea","required":true,"maxLength":16000}]}}]},{"key":"collection","label":"Collection","type":"object","fields":[{"key":"h2","label":"H2","type":"text","required":true,"maxLength":500},{"key":"shopAll","label":"Shop All","type":"text","required":true,"maxLength":500},{"key":"cards","label":"Cards","type":"list","min":0,"max":100,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"id","label":"Id","type":"text","required":true,"maxLength":500},{"key":"title","label":"Title","type":"text","required":true,"maxLength":500},{"key":"description","label":"Description","type":"textarea","required":true,"maxLength":16000},{"key":"count","label":"Count","type":"text","required":false,"maxLength":500},{"key":"linkText","label":"Link Text","type":"textarea","required":true,"maxLength":16000},{"key":"href","label":"Href","type":"url","required":true,"maxLength":2048}]}}]},{"key":"closingCta","label":"Closing Cta","type":"object","fields":[{"key":"h2","label":"H2","type":"text","required":true,"maxLength":500},{"key":"sub","label":"Sub","type":"text","required":true,"maxLength":500},{"key":"primaryCta","label":"Primary Cta","type":"text","required":true,"maxLength":500},{"key":"secondaryCta","label":"Secondary Cta","type":"text","required":true,"maxLength":500},{"key":"whatsappCta","label":"Whatsapp Cta","type":"text","required":true,"maxLength":500}]}]}]},"route":"/about"},{"slug":"faq","kind":"page","title":"Frequently asked questions","description":"Website content and search information for Frequently asked questions.","publish":true,"content":{"seo":{"title":"Frequently Asked Questions | Seedly Pakistan","description":"Answers about raw seeds, mountain teas, seed cycling routines, nationwide delivery across Pakistan, and our 7-day quality guarantee."},"copy":{"text_answers_guidance":"Answers & Guidance","text_frequently_asked_questions":"Frequently Asked Questions","text_clear_facts_on_our_smallholder_sourcing_cold_milling_st":"Clear facts on our smallholder sourcing, cold-milling standards, brewing parameters, and nationwide courier delivery.","text_still_have_a_question":"Still have a question?","text_our_lahore_pantry_team_is_available_monday_to_saturday":"Our Lahore pantry team is available Monday to Saturday (9am–7pm PKT) to guide you on seed routines, batch origin, or courier tracking.","text_whatsapp":"WhatsApp (","text_contact_care_team":"Contact & Care Team"},"links":{"href_contact":"/contact"},"images":{},"sections":[{"id":"page_section_01","enabled":true}],"items":[{"category":"Seed Routines & Usage","question":"What is seed cycling and how does it work?","answer":"Seed cycling is a traditional whole-food dietary habit where you rotate four nutrient-dense pantry seeds between the two phases of your monthly cycle. During Phase 1 (Days 1–14, Follicular), raw pumpkin seeds and cold-milled golden flax provide dietary magnesium, zinc, and plant-based ALA omega-3 fatty acids. During Phase 2 (Days 15–28, Luteal), raw sunflower kernels and unhulled sesame seeds supply natural Vitamin E, selenium, and essential minerals. While popular as a gentle dietary habit, research is early and limited. Individuals with PCOS, thyroid conditions, or who are pregnant or nursing should speak with their physician."},{"category":"Seed Routines & Usage","question":"Do I need to grind Seedly Golden Flax Seeds at home?","answer":"No grinding required! Whole flax seeds have a tough outer cellulose husk that passes through the digestive tract unabsorbed unless milled. To save you time and maximize nutrient absorption, Seedly Golden Flax is already freshly cold-milled into a coarse meal in small batches right here in Lahore. It arrives ready to spoon straight into yogurt bowls, warm oatmeal, or morning smoothies."},{"category":"Seed Routines & Usage","question":"How long does a 250g pouch or Complete Kit last?","answer":"Based on the standard daily serving of 1 level tablespoon (approx. 8–10g), a single 250g pouch provides roughly 25–30 daily servings. Our Complete Cycle Kit contains four separate 250g pouches (1kg total) plus a wooden measured scoop and cycle calendar, providing approximately 50–60 daily servings—enough for two complete 28-day cycles."},{"category":"Mountain Teas & Brewing","question":"Why does Seedly use loose whole chamomile flowers instead of teabags?","answer":"Commercial teabags frequently contain finely pulverized \"tea dust\" (fannings) that leach bitter tannins, and many bags contain microplastics or bleached paper fibers. Our whole chamomile flowers are intact blossoms harvested by smallholder growers in high mountain valleys of Gilgit-Baltistan, delivering a clean, sweet honey-apple infusion without microplastics or artificial additives."},{"category":"Mountain Teas & Brewing","question":"What are the recommended water temperatures and steeping times?","answer":"For Pure Chamomile Flowers: 1 rounded teaspoon (approx. 2.5g) in 200–250ml freshly boiled water (95–100°C), steeping 5–7 minutes for a soothing evening cup (yields approx. 20 cups per 50g pack). For Highland Spearmint Leaf: 1 teaspoon (approx. 2g) in 90–95°C water, steeping 4–5 minutes. For Highland Green Tea: 1 teaspoon in cooler water (approx. 80°C) for 2–3 minutes to avoid bitter astringency."},{"category":"Mountain Teas & Brewing","question":"Are your herbal teas caffeine-free?","answer":"Both our Pure Mountain Chamomile Flowers and Highland Spearmint Leaf teas are 100% naturally caffeine-free herbal tisanes that can be enjoyed any time of day or night. Highland Green Tea contains a gentle amount of natural caffeine (approx. 20–25mg per cup)."},{"category":"Storage & Freshness","question":"What is the shelf life and how should seeds be stored?","answer":"Whole raw seeds (pumpkin, sunflower, unhulled sesame) stay fresh for 12 months when stored in a cool, dry, dark pantry in their airtight barrier pouches. Because cold-milled flax meal contains fragile polyunsaturated omega-3 fatty acids, it has a 9-month sealed shelf life. Once opened, we strongly recommend storing cold-milled flax in the refrigerator and consuming it within 60–90 days for peak freshness."},{"category":"Allergen Advisory","question":"What allergens are handled in your facility?","answer":"All Seedly products are cleaned and packed in a Lahore facility that also handles edible seeds (sesame, sunflower, pumpkin, flax), mustard, and tree nuts (almonds, walnuts). In addition, individuals with known sensitivities to the Asteraceae / Daisy plant family (e.g. ragweed, chrysanthemums) should exercise caution with chamomile infusions."},{"category":"Shipping & Delivery","question":"How fast is nationwide courier delivery across Pakistan?","answer":"All orders are dispatched daily from our central Lahore hub via TCS and Leopards Courier. Expected transit windows are: Lahore (1–2 business days); rest of Punjab and Islamabad/Rawalpindi (2–3 business days); Sindh (including Karachi), Khyber Pakhtunkhwa, and Balochistan (3–4 business days); Gilgit-Baltistan and Azad Jammu & Kashmir (4–6 business days)."},{"category":"Shipping & Delivery","question":"How does Free Delivery work?","answer":"Current delivery charges and the free-delivery threshold are shown in your basket before checkout. See our shipping page for delivery information."},{"category":"Payments & Verification","question":"What payment methods do you accept?","answer":"We accept Cash on Delivery (COD) across Pakistan, allowing you to pay the courier rider in cash upon parcel arrival. We also accept digital wallet payments via JazzCash and Easypaisa, as well as direct online bank transfer (IBFT). Note that direct digital payments are verified manually by our accounts team against your transaction ID or screenshot prior to dispatch."},{"category":"Quality & Returns","question":"What does your 7-Day Guarantee cover?","answer":"Under our 7-Day Quality & Freshness Guarantee, if any item arrives damaged, crushed, unsealed, incorrect, or with a verified quality or freshness concern (such as unexpected staleness or rancidity), we will dispatch a free replacement immediately at our expense or issue a full refund to your original payment method. Reach out via WhatsApp at 0371 9055758 within 7 days of delivery."}]},"definition":{"slug":"faq","title":"Frequently asked questions","description":"Website content and search information for Frequently asked questions.","kind":"page","fields":[{"key":"seo","label":"Seo","type":"object","fields":[{"key":"title","label":"Title","type":"text","required":true,"maxLength":500},{"key":"description","label":"Description","type":"textarea","required":true,"maxLength":16000}]},{"key":"copy","label":"Copy","type":"object","fields":[{"key":"text_answers_guidance","label":"Answers guidance","type":"textarea","required":true,"maxLength":16000},{"key":"text_frequently_asked_questions","label":"Frequently asked questions","type":"textarea","required":true,"maxLength":16000},{"key":"text_clear_facts_on_our_smallholder_sourcing_cold_milling_st","label":"Clear facts on our smallholder sourcing cold milling st","type":"textarea","required":true,"maxLength":16000},{"key":"text_still_have_a_question","label":"Still have a question","type":"textarea","required":true,"maxLength":16000},{"key":"text_our_lahore_pantry_team_is_available_monday_to_saturday","label":"Our lahore pantry team is available monday to saturday","type":"textarea","required":true,"maxLength":16000},{"key":"text_whatsapp","label":"Whatsapp","type":"textarea","required":true,"maxLength":16000},{"key":"text_contact_care_team","label":"Contact care team","type":"textarea","required":true,"maxLength":16000}]},{"key":"links","label":"Links","type":"object","fields":[{"key":"href_contact","label":"Contact","type":"url","required":true,"maxLength":2048}]},{"key":"images","label":"Images","type":"object","fields":[]},{"key":"sections","label":"Sections","type":"list","min":1,"max":1,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"id","label":"Id","type":"select","required":true,"options":[{"value":"page_section_01","label":"page section 01"}],"maxLength":80},{"key":"enabled","label":"Enabled","type":"boolean"}]}},{"key":"items","label":"Items","type":"list","min":0,"max":100,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"category","label":"Category","type"