imings.","text_returns_replacements":"Returns & replacements","text_7_day_guarantee_details_and_how_to_initiate_a_claim":"7-day guarantee details and how to initiate a claim.","text_frequently_asked_questions":"Frequently asked questions","text_answers_about_cold_milled_seeds_brewing_and_storage":"Answers about cold-milled seeds, brewing, and storage."},"links":{"href_shipping":"/shipping","href_returns":"/returns","href_faq":"/faq"},"images":{},"sections":[{"id":"page_section_01","enabled":true}]},"definition":{"slug":"contact","title":"Contact Seedly","description":"Website content and search information for Contact Seedly.","kind":"page","fields":[{"key":"seo","label":"Seo","type":"object","fields":[{"key":"title","label":"Title","type":"text","required":true,"maxLength":500},{"key":"description","label":"Description","type":"textarea","required":true,"maxLength":16000}]},{"key":"copy","label":"Copy","type":"object","fields":[{"key":"text_customer_care","label":"Customer care","type":"textarea","required":true,"maxLength":16000},{"key":"text_contact_seedly","label":"Contact seedly","type":"textarea","required":true,"maxLength":16000},{"key":"text_a_question_about_your_order_choosing_seeds_or_brewing_y","label":"A question about your order choosing seeds or brewing y","type":"textarea","required":true,"maxLength":16000},{"key":"text_ways_to_get_in_touch","label":"Ways to get in touch","type":"textarea","required":true,"maxLength":16000},{"key":"text_whatsapp","label":"Whatsapp","type":"textarea","required":true,"maxLength":16000},{"key":"text_instant_order_assistance_address_confirmations_and_pers","label":"Instant order assistance address confirmations and pers","type":"textarea","required":true,"maxLength":16000},{"key":"text_message_on_whatsapp","label":"Message on whatsapp","type":"textarea","required":true,"maxLength":16000},{"key":"text_phone","label":"Phone","type":"textarea","required":true,"maxLength":16000},{"key":"text_speak_directly_with_our_care_desk_