mages","type":"object","fields":[]},{"key":"sections","label":"Sections","type":"list","min":3,"max":3,"item":{"key":"item","label":"Item","type":"object","fields":[{"key":"id","label":"Id","type":"select","required":true,"options":[{"value":"page_section_01","label":"page section 01"},{"value":"page_section_02","label":"page section 02"},{"value":"page_section_03","label":"page section 03"}],"maxLength":80},{"key":"enabled","label":"Enabled","type":"boolean"}]}}]},"route":"/returns"},{"slug":"privacy","kind":"page","title":"privacy","description":"Website content and search information for privacy.","publish":true,"content":{"seo":{"title":"Privacy Policy | Seedly Pakistan","description":"How Seedly protects and handles your personal information. Safe, transparent customer data practices for nationwide orders in Pakistan."},"copy":{"text_data_protection":"Data Protection","text_privacy_policy":"Privacy Policy","text_how_seedly_respects_handles_and_safeguards_your_custome":"How Seedly respects, handles, and safeguards your customer information across our website and delivery network.","text_1_information_we_collect":"1. Information We Collect","text_we_collect_personal_information_necessary_to_deliver_yo":"We collect personal information necessary to deliver your orders and provide helpful customer care: your name, shipping address, landmark, city, email address, mobile contact number, and payment verification references.","text_2_routine_questionnaire_interactive_tools":"2. Routine Questionnaire & Interactive Tools","text_when_you_use_our_routine_finder_questionnaire_cycle_cal":"When you use our Routine Finder questionnaire, cycle calendar, or brew guides, any responses you provide are processed in-session or on your device solely to suggest relevant whole-food ingredients and guidance. We never sell, rent, or share your routine questionnaire answers with third parties or advertisers.","text_3_email_newsletter_communications":"3. Email Newsletter & Communications","text_if_you_subscribe_to_our_fresh_dispatches_newsletter_we":"If you subscribe to our Fresh Dispatches newsletter, we store your email address solely to send seasonal harvest announcements, pantry recipes, and store updates. You may opt out or unsubscribe at any time via the one-click unsubscribe link at the bottom of every email dispatch.","text_4_payment_processing_verification":"4. Payment Processing & Verification","text_seedly_does_not_collect_process_or_store_credit_debit_c":"Seedly does not collect, process, or store credit/debit card numbers or confidential banking passwords. For Cash on Delivery (COD), payment is made directly to the courier rider upon delivery. For manual transfers via JazzCash, Easypaisa, or direct bank transfer (IBFT), payment transaction IDs and verification screenshots are inspected solely by our internal Lahore accounts team to verify settlement prior to parcel dispatch.","text_5_courier_logistics_partners":"5. Courier Logistics Partners","text_to_fulfill_your_physical_delivery_we_share_your_recipie":"To fulfill your physical delivery, we share your recipient name, destination address, and mobile phone number strictly with our contracted courier logistics partners—","text_tcs":"TCS","text_and":" and ","text_leopards_courier":"Leopards Courier","text_they_use_this_data_solely_to_transport_the_parcel_and_s":". They use this data solely to transport the parcel and send you SMS tracking and delivery arrival notifications.","text_6_cookies_anonymous_analytics":"6. Cookies & Anonymous Analytics","text_we_use_essential_first_party_cookies_to_remember_your_s":"We use essential first-party cookies to remember your shopping cart items across visits and retain session preferences. We also use privacy-focused, anonymous site telemetry to monitor page loading speed and technical reliability. We do not use third-party behavioral advertising trackers.","text_7_your_data_rights":"7. Your Data Rights","text_you_have_the_right_to_request_access_to_correction_of_o":"You have the right to request access to, correction of, or deletion of your customer information at any time. Simply contact our support team via WhatsApp at","text_or_email":"or email"},"links":{},"images":{},"sections":[{"id":"page_section_01","enabled":true},{"id":"page_section_02","enabled":true},{"id":"page_section_03","enabled":true},{"id":"page_section_04","enabled":true},{"id":"page_section_05","enabled":true},{"id":"page_section_06","enabled":true},{"id":"page_section_07","enabled":true}]},"definition":{"slug":"privacy","title":"privacy","description":"Website content and search information for privacy.","kind":"page","fields":[{"key":"seo","label":"Seo","type":"object","fields":[{"key":"title","label":"Title","type":"text","required":true,"maxLength":500},{"key":"description","label":"Description","type":"textarea","required":true,"maxLength":16000}]},{"key":"copy","label":"Copy","type":"object","fields":[{"key":"text_data_protection","label":"Data protection","type":"textarea","required":true,"maxLength":16000},{"key":"text_privacy_policy","label":"Privacy policy","type":"textarea","required":true,"maxLength":16000},{"key":"text_how_seedly_respects_handles_and_safeguards_your_custome","label":"How seedly respects handles and safeguards your custome","type":"textarea","required":true,"maxLength":16000},{"key":"text_1_information_we_collect","label":"1 information we collect","type":"textarea","required":true,"maxLength":16000},{"key":"text_we_collect_personal_information_necessary_to_deliver_yo","label":"We collect personal information necessary to deliver yo","type":"textarea","required":true,"maxLength":16000},{"key":"text_2_routine_questionnaire_interactive_tools","label":"2 routine questionnaire interactive tools","type":"textarea","required":true,"maxLength":16000},{"key":"text_when_you_use_our_routine_finder_questionnaire_cycle_cal","label":"When you use our routine finder questionnaire cycle cal","type":"textarea","required":true,"max